import Cocoa
import Darwin
import FlutterMacOS

/// Protected pasteboard for secrets (S9): `consolecrypt/clipboard`.
///
/// * `.currentHostOnly` keeps the item off Universal Clipboard;
/// * `org.nspasteboard.ConcealedType` (secrets and private text) and
///   `org.nspasteboard.TransientType` (secrets: cleared soon) ask clipboard
///   managers not to show or record it; `AutoGeneratedType` marks text the
///   app put there without a user action (RDP);
/// * the ownership token is `changeCount@bootTime`: the change count after
///   our write, plus the boot time so a count repeated after a restart is not
///   taken for ours. Ownership is checked from the change count and the
///   marker types only: the content is never read (no paste prompts).
enum SecretPasteboard {
  private static let concealed = NSPasteboard.PasteboardType("org.nspasteboard.ConcealedType")
  private static let transient = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")
  private static let autoGenerated = NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType")

  /// The last secret token, cleared on quit if still ours.
  private static var lastSecret: String?

  private static let bootTime: Int = {
    var time = timeval()
    var size = MemoryLayout<timeval>.stride
    var mib: [Int32] = [CTL_KERN, KERN_BOOTTIME]
    return sysctl(&mib, 2, &time, &size, nil, 0) == 0 ? Int(time.tv_sec) : 0
  }()

  /// Writes [text]; returns the ownership token.
  static func copy(_ text: String, secret: Bool, autoGeneratedContent: Bool) -> String? {
    let pasteboard = NSPasteboard.general
    // macOS 12+ (the deployment target): not offered to Universal Clipboard.
    _ = pasteboard.prepareForNewContents(with: .currentHostOnly)
    guard pasteboard.setString(text, forType: .string) else { return nil }
    pasteboard.setData(Data(), forType: concealed)
    if secret { pasteboard.setData(Data(), forType: transient) }
    if autoGeneratedContent { pasteboard.setData(Data(), forType: autoGenerated) }
    let token = "\(pasteboard.changeCount)@\(bootTime)"
    lastSecret = secret ? token : nil
    return token
  }

  /// `cleared` if the pasteboard still holds the clip of [token], otherwise
  /// `foreign` (something else is there) or `gone` (empty).
  static func clearIfOwned(_ token: String) -> String {
    let pasteboard = NSPasteboard.general
    let parts = token.split(separator: "@", maxSplits: 1).map(String.init)
    if parts.count == 2, let count = Int(parts[0]), Int(parts[1]) == bootTime,
       pasteboard.changeCount == count, pasteboard.types?.contains(concealed) == true {
      pasteboard.clearContents()
      if lastSecret == token { lastSecret = nil }
      return "cleared"
    }
    if lastSecret == token { lastSecret = nil }
    return (pasteboard.types ?? []).isEmpty ? "gone" : "foreign"
  }

  /// On quit (ТР-10): a secret still on the pasteboard does not outlive us.
  static func clearOnExit() {
    if let token = lastSecret { _ = clearIfOwned(token) }
  }

  static func forget() { lastSecret = nil }
}

/// Method channel for [SecretPasteboard].
final class SecretPasteboardBridge {
  private let channel: FlutterMethodChannel

  init(messenger: FlutterBinaryMessenger) {
    channel = FlutterMethodChannel(name: "consolecrypt/clipboard", binaryMessenger: messenger)
    channel.setMethodCallHandler { call, result in
      let arguments = call.arguments as? [String: Any]
      switch call.method {
      case "copySecret", "copyPrivate":
        guard let text = arguments?["text"] as? String else {
          result(FlutterError(code: "bad_args", message: "Invalid clipboard request", details: nil))
          return
        }
        let secret = call.method == "copySecret"
        let token = SecretPasteboard.copy(
          text, secret: secret, autoGeneratedContent: secret && (arguments?["autoGenerated"] as? Bool ?? false))
        if token == nil {
          result(FlutterError(code: "clipboard", message: "Secret clipboard unavailable", details: nil))
        } else {
          result(secret ? token : nil)
        }
      case "clearIfOwned":
        guard let token = arguments?["token"] as? String, !token.isEmpty else {
          result(FlutterError(code: "bad_args", message: "Invalid clipboard token", details: nil))
          return
        }
        result(SecretPasteboard.clearIfOwned(token))
      case "forget":
        SecretPasteboard.forget()
        result(nil)
      default:
        result(FlutterMethodNotImplemented)
      }
    }
  }
}
